use std::{fs,path::Path,collections::BTreeMap,io::Read};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn main(){let r=Path::new("/tmp/zopro-base-census");let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let a=read("/tmp/zopro-grouping-module/native/candidate/artifacts.json");let mut pins=BTreeMap::new();for(rel,h)in m["source_files_sha256"].as_object().unwrap(){let p=Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel);assert_eq!(hash(&p),h.as_str().unwrap());pins.insert(p.display().to_string(),hash(p));}for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),hash(p));}for c in read(r.join("cases.json")).as_array().unwrap(){let p=c["image"].as_str().unwrap();pins.insert(p.to_owned(),hash(p));}for rel in ["cases.json","design.md","probe.rs","prepare.rs","finish.rs","finish"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}
 let mut argv=vec![json!("rustc"),json!("--edition=2021"),json!("-O"),json!("-C"),json!("target-cpu=native"),json!("-C"),json!("lto=off"),json!("-C"),json!("codegen-units=1"),json!("-L"),json!("dependency=/tmp/zopro-grouping-module/target-native/release/deps")];for name in ["zopro_prover","zopro_bn254","memmap2","serde_json"]{argv.extend([json!("--extern"),json!(format!("{name}={}",a["libraries"][name].as_str().unwrap()))]);}let mut test=argv.clone();test.extend([json!("--test"),json!(r.join("probe.rs")),json!("-o"),json!(r.join("probe-tests"))]);argv.extend([json!(r.join("probe.rs")),json!("-o"),json!(r.join("probe"))]);let plan=json!({"version":1,"source_pins":r.join("input-pins.json"),"environment":m["environment"],"steps":[{"kind":"command","name":"link","argv":argv,"timeout_seconds":600},{"kind":"command","name":"link-tests","argv":test,"timeout_seconds":600},{"kind":"command","name":"tests","argv":[r.join("probe-tests")],"required_tests":["tests::signed_counts_match_independent_sorted_sets","tests::signed_scalar_combination_matches_g1_and_g2_generator_oracles","tests::zero_only_counts_no_classes","tests::range_arithmetic_rejects_overflow_and_truncation"],"unfiltered":true,"timeout_seconds":120},{"kind":"command","name":"census","argv":["/usr/bin/time","-v","taskset","-c","0-31",r.join("probe"),r.join("cases.json")],"timeout_seconds":1200}]});fs::write(r.join("input-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r.join("plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Pinned{}inputs,9images;acceptedsourceunchanged",pins.len());}
